def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for k, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opponents.append((k, o))
        except Exception:
            pass

    # If no one is alive, spend conservatively.
    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only (immediate reaction).
    prev_bids = []
    for _, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Pressure estimate: if others bid high yesterday, the market is competitive.
    pressure = 0.0
    if prev_bids:
        pressure = max(prev_bids)

    # Base aggressiveness tied to how close supply is to requirement.
    # If supply is tight, winning water matters more.
    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    tightness = max(0.0, min(1.0, tightness))

    # Urgency: if we've already had no water days, bid more.
    urgency = 0.0
    if no_water_days >= 2:
        urgency = 1.0
    elif no_water_days == 1:
        urgency = 0.5

    # Budget-aware cap: never commit more than a fraction of budget.
    # If low hp, we must secure water.
    if hp <= 2.0:
        budget_cap = 0.95
    elif hp <= 4.0:
        budget_cap = 0.75
    else:
        budget_cap = 0.6

    # Target bid logic:
    # - If yesterday pressure was high, outbid slightly.
    # - Otherwise, bid enough to be competitive but not wasteful.
    if pressure > 0.0:
        # If someone bid near salary previously, competition is intense.
        if pressure >= DAILY_SALARY * 0.85:
            target = DAILY_SALARY * (0.35 + 0.35 * tightness + 0.3 * urgency)
            # Outbid by a small margin proportional to pressure.
            target = max(target, pressure + 2.0)
        else:
            target = max(DAILY_SALARY * (0.45 + 0.25 * tightness + 0.2 * urgency), pressure * 0.9 + 1.5)
    else:
        target = DAILY_SALARY * (0.5 + 0.25 * tightness + 0.25 * urgency)

    # Convert to final bid with budget and non-negativity constraints.
    max_affordable = budget_cap * budget
    bid = min(max_affordable, target)

    # Ensure we don't bid negative.
    if bid < 0.0:
        bid = 0.0

    # Small day-based adjustment: later days slightly more aggressive.
    # (day_context day is available; keep mild to avoid overspending.)
    try:
        bid = bid * (1.0 + 0.02 * max(0, day - 1))
    except Exception:
        pass

    # Final clamp to budget.
    if bid > budget:
        bid = budget

    return float(bid)

