    if scarcity > 1:
        scarcity = 1.0

    base = 28.0 + 26.0 * scarcity

    if supply >= 22:
        base -= 8.0
    elif supply <= 17:
        base += 12.0

    if hp <= 2:
        base = max(base, 88.0)
    elif hp <= 4:
        base = max(base, 68.0)
