    if prev_bids:
        if max_prev_bid >= 120:
            if hp >= 5 and supply >= 20:
                base = min(base, 34.0)
            else:
                base = max(base, min(max_prev_bid + 2.0, 92.0))
        elif max_prev_bid >= 75:
            base = max(base, min(max_prev_bid + 1.5, 86.0))
        else:
            base = max(base, max_prev_bid + 1.0)

