        base -= 6.0

    if budget < DAILY_SALARY:
        base = min(base, budget * 0.72)

    if day >= 8:
        if hp <= 4:
            base = max(base, 78.0)
        else:
            base += 4.0

    if max_prev_budget < 80 and hp >= 4:
        base -= 5.0

    bid = max(0.0, min(float(budget), base))
