def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_budget, 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = max(yesterday_bids) if yesterday_bids else 0.0

    base_bid = DAILY_SALARY * 0.5

    if my_hp <= 2:
        bid = DAILY_SALARY * 0.95
    elif my_hp <= 4:
        bid = DAILY_SALARY * 0.8
    else:
        bid = base_bid

    if yesterday_bids:
        if max_yesterday_bid >= DAILY_SALARY * 0.9:
            if my_hp <= 4:
                bid = max(bid, max_yesterday_bid + 5.0)
            else:
                bid = max(bid, max_yesterday_bid * 0.95)
        elif max_yesterday_bid > DAILY_SALARY * 0.5:
            bid = max(bid, max_yesterday_bid + 2.0)
        else:
            bid = max(bid, DAILY_SALARY * 0.4)

    possible_recipients = int(current_supply // WATER_REQ)

    if num_alive_opponents + 1 > possible_recipients and possible_recipients > 0:
        bid *= 1.1
    elif num_alive_opponents + 1 <= possible_recipients:
        bid *= 0.9

    bid = min(bid, my_budget)
    bid = max(bid, 1.0)

    days_left = EPISODE_DAYS - current_day + 1
    if days_left > 0:
        average_daily_budget_needed = my_budget / days_left
        if bid > average_daily_budget_needed * 1.5 and my_hp > 2:
            bid = min(bid, average_daily_budget_needed * 1.2)

    if my_budget < DAILY_SALARY and my_hp > 3:
        bid = min(bid, DAILY_SALARY * 0.3)

    return bid
